FriBidiRun *
new_run (
  void
)
{
  register FriBidiRun *run;

  run = fribidi_malloc (sizeof (FriBidiRun));

  if LIKELY
    (run)
    {
      run->len = run->pos = run->level = run->isolate_level = 0;
      run->next = run->prev = run->prev_isolate = run->next_isolate = NULL;
    }
  return run;
}

